package main

import (
	"crypto/subtle"
	"fmt"
)

func constantTimeCompare(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1
}

func main() {
	fmt.Println(constantTimeCompare("password123", "password123")) // true
	fmt.Println(constantTimeCompare("password123", "password124")) // false
}
